@font-face {
  font-family: 'Nunito Sans';
  font-style: normal;
  font-weight: 700 700;
  font-stretch: normal;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

@font-face {
  font-family: 'Nunito Sans';
  font-style: normal;
  font-weight: 800 800;
  font-stretch: normal;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

@font-face {
  font-family: 'Outfit';
  font-style: normal;
  font-weight: 400 400;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

@font-face {
  font-family: 'Outfit';
  font-style: normal;
  font-weight: 500 500;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

@font-face {
  font-family: 'Outfit';
  font-style: normal;
  font-weight: 600 600;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

@font-face {
  font-family: 'Outfit';
  font-style: normal;
  font-weight: 700 700;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

@font-face {
  font-family: 'Outfit';
  font-style: normal;
  font-weight: 800 800;
  font-display: swap;
  src: url(data:font/truetype;base64,) format('truetype');
}

:root {
  color-scheme: dark;
  --bg: #0b1022;
  --panel: #171e39;
  --line: #364565;
  --ink: #f4f5ff;
  --muted: #bbc9e0;
  --blue: #a4c8ff;
  --orange: #ffd094;
  --green: #95edcf;
  --red: #ffa3b3;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-attachment: fixed;
  color: var(--ink);
  font: 15px/1.6 'Nunito Sans',system-ui,sans-serif;
  font-size: 16px;
  line-height: 1.65;
  isolation: isolate;
  background: #0b1022;
  padding-bottom: 128px;
}

button {
  font: inherit;
  cursor: pointer;
  color: inherit;
  border: 1px solid var(--line);
  background: #14253a;
  padding: 11px 18px;
  transition: background .2s,transform .2s,border-color .2s;
  border-radius: 12px;
  min-height: 44px;
}

input {
  font: inherit;
}

select {
  font: inherit;
}

button:hover {
  background: #203950;
  border-color: var(--blue);
  transform: translateY(-2px);
}

button:active {
  transform: scale(.98);
}

button:disabled {
  opacity: .4;
  box-shadow: none;
  cursor: not-allowed;
}

button:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

a:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

input:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

a {
  color: var(--blue);
}

h1 {
  margin: 0;
  font-family: 'Outfit',system-ui,sans-serif;
  letter-spacing: -.035em;
  line-height: 1.1;
  font-size: clamp(48px,5.3vw,82px);
  font-weight: 800;
}

h2 {
  margin: 0;
  font-weight: 700;
  font-family: 'Outfit',system-ui,sans-serif;
  letter-spacing: -.035em;
  line-height: 1.1;
  font-size: clamp(28px,3.4vw,42px);
}

h3 {
  margin: 0;
  font-family: 'Outfit',system-ui,sans-serif;
  letter-spacing: -.035em;
  line-height: 1.1;
  font-size: 23px;
}

p {
  margin: 0;
  color: var(--muted);
}

.display {
  font-family: 'Outfit',system-ui,sans-serif;
  letter-spacing: -.035em;
  line-height: 1.1;
}

#stars {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: -1;
  opacity: 1;
}

header {
  max-width: 1480px;
  margin: auto;
  min-height: 94px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 32px;
  border-bottom: 1px solid #253447;
  border-bottom-color: #879bd42b;
}

.brand {
  display: flex;
  gap: 13px;
  align-items: center;
  text-decoration: none;
  font-size: 16px;
  letter-spacing: .1em;
  color: white;
  font-family: 'Outfit',sans-serif;
}

.brand b {
  color: var(--blue);
  font-weight: 500;
}

.brand small {
  display: block;
  font-size: 9px;
  color: #b3c4d4;
  margin-top: 3px;
  letter-spacing: .13em;
}

.brand-icon {
  font-size: 35px;
  color: #c9b4ff;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.small {
  padding: 7px 11px;
  font-size: 12px;
  min-height: 38px;
}

.live {
  font-size: 10px;
  color: var(--green);
  letter-spacing: .12em;
  display: none;
}

main {
  max-width: 1400px;
  margin: auto;
  padding: 32px;
}

.eyebrow {
  font: 700 11px/1.5 'Nunito Sans',sans-serif;
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: 11px;
  color: #c0baff;
}

.hero {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  align-items: center;
  gap: 40px;
  min-height: 550px;
}

.hero h1 {
  margin: 20px 0;
}

.hero h1 span {
  background: linear-gradient(120deg,#b8d9ff,#c4b0ff 65%,#ffcfa2);
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
}

.hero .intro {
  font-size: 18px;
  max-width: 530px;
}

.hero-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 28px 0 16px;
}

.primary {
  font-weight: 800;
  background: #d6c4ff;
  color: #17203b;
  border-color: #d6c4ff;
  border-radius: 14px;
  box-shadow: 0 5px 24px #ad8dff20;
}

.primary:hover {
  background: #e3d7ff;
  border-color: #efe7ff;
}

.secondary {
  border-color: #829ac2;
  border-radius: 14px;
}

.panel {
  border: 1px solid var(--line);
  overflow: hidden;
  border-radius: 19px;
  border-color: #4154778f;
  background: linear-gradient(135deg,#1b2740e0,#141d32ec);
}

.hero-scene {
  position: relative;
  height: 510px;
  overflow: hidden;
}

.hero-scene canvas {
  width: 100%;
  height: 100%;
  opacity: .93;
}

.scene-caption {
  position: absolute;
  display: flex;
  justify-content: space-between;
  align-items: end;
  font-size: 11px;
  color: var(--muted);
  bottom: 24px;
  left: 24px;
  right: 24px;
  gap: 16px;
}

.scene-caption b {
  display: block;
  color: var(--ink);
  font-size: 14px;
}

.pill {
  display: inline-block;
  border: 1px solid #53718b;
  color: var(--blue);
  border-radius: 20px;
  font-size: 10px;
  letter-spacing: .05em;
  padding: 5px 10px;
}

.features {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  margin: 32px 0;
  gap: 12px;
}

.feature {
  padding: 22px;
  border-top: 1px solid var(--line);
  border: 1px solid #3c507256;
  border-radius: 18px;
  background: #18233a70;
}

.feature b {
  display: block;
  margin: 8px 0;
  font-family: 'Outfit',sans-serif;
  font-size: 18px;
}

.feature p {
  font-size: 14px;
}

.num {
  font-family: monospace;
  color: #c3b3ff;
}

.section-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 25px;
}

.section-top h2 {
  margin-top: 7px;
  letter-spacing: -.035em;
}

.section-top p {
  margin-top: 8px;
  font-size: 15px;
}

.hud {
  display: grid;
  grid-template-columns: repeat(7,minmax(0,1fr));
  margin-bottom: 24px;
  gap: 10px;
}

.stat {
  padding: 13px 14px;
  border: 1px solid var(--line);
  min-width: 0;
  position: relative;
  border-radius: 14px;
  background: #17233c;
}

.stat-label {
  text-transform: uppercase;
  color: #b9cadb;
  font-size: 11px;
  letter-spacing: .025em;
}

.stat b {
  display: block;
  line-height: 1.5;
  white-space: nowrap;
  font-family: 'Outfit',sans-serif;
  font-size: 26px;
}

.stat small {
  font-size: 11px;
  color: var(--muted);
}

.bar {
  height: 4px;
  background: #283d51;
  margin-top: 8px;
  border-radius: 4px;
  overflow: hidden;
}

.bar span {
  height: 100%;
  display: block;
  background: var(--blue);
  transition: width .6s;
}

.stat.warn {
  border-color: #aa654b;
}

.stat.warn b {
  color: var(--orange);
}

.stat.danger {
  border-color: #c35a70;
  animation: none;
}

.stat.danger b {
  color: var(--red);
}

.two-col {
  display: grid;
  grid-template-columns: minmax(0,1fr) 310px;
  gap: 24px;
  align-items: start;
}

.side {
  display: grid;
  gap: 16px;
}

.side .panel {
  padding: 20px;
}

.side h3 {
  font-size: 22px;
  margin-bottom: 13px;
}

.equip-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 12px;
}

.equipment {
  text-align: left;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-width: 0;
  border-radius: 18px;
  background: #17253c;
  padding: 18px;
  gap: 12px;
}

.equipment.on {
  background: #203e51;
  border-color: #a0e8d2;
  box-shadow: 0 0 0 2px #8ee3c21a;
}

.equipment .top {
  display: flex;
  justify-content: space-between;
  gap: 5px;
  font-size: 10px;
  color: var(--blue);
  min-height: 20px;
  letter-spacing: .03em;
}

.equipment h3 {
  font: 700 14px/1.4 'Nunito Sans',sans-serif;
  font-family: 'Outfit',sans-serif;
  font-size: 17px;
  min-height: 44px;
}

.equipment p {
  line-height: 1.5;
  font-size: 13px;
  min-height: 58px;
}

.equipment .art {
  height: 112px;
  border-radius: 13px;
}

.equipment .effect {
  font: 600 11px/1.6 'Nunito Sans',sans-serif;
  color: var(--green);
  min-height: 36px;
  font-size: 12px;
  line-height: 1.65;
}

.equipment .cost {
  display: flex;
  justify-content: space-between;
  padding-top: 9px;
  margin-top: auto;
  border-top: 1px solid var(--line);
  font-size: 14px;
}

.art {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  overflow: hidden;
  background: radial-gradient(ellipse,#203f59,#0b1524);
  position: relative;
}

.art svg {
  height: 100%;
  max-width: 100%;
  display: block;
}

.art svg .rotate {
  transform-origin: 90px 60px;
  animation: rotate 12s linear infinite;
}

.art svg .float {
  animation: bob 3s ease-in-out infinite;
}

.launch-box {
  margin-top: 18px;
  padding: 22px;
}

.requirements {
  font-size: 12px;
  display: grid;
  gap: 7px;
  margin: 15px 0;
}

.requirements .ok {
  color: var(--green);
}

.requirements .bad {
  color: var(--orange);
}

.load-list {
  display: grid;
  gap: 9px;
  font-size: 12px;
}

.load-list div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #26394d;
  padding-bottom: 7px;
}

.hangar {
  height: 240px;
  margin-bottom: 16px;
  position: relative;
}

.hangar canvas {
  width: 100%;
  height: 100%;
}

.tagline {
  color: var(--muted);
  margin-top: 12px;
  font-size: 13px;
}

.phase-strip {
  display: flex;
  gap: 0;
  margin-bottom: 22px;
  overflow: auto;
}

.phase-step {
  flex: 1;
  min-width: 100px;
  border-bottom: 2px solid var(--line);
  padding: 10px 8px;
  color: var(--muted);
  font-size: 12px;
}

.phase-step.active {
  color: #d9c5ff;
  border-color: #d9c5ff;
}

.phase-step.done {
  border-color: var(--green);
  color: var(--green);
}

.mission-scene {
  position: relative;
  margin-bottom: 20px;
  overflow: hidden;
  border-radius: 24px;
  height: 290px;
}

.mission-scene canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.scene-overlay {
  position: absolute;
  inset: 18px;
  display: flex;
  justify-content: space-between;
  align-items: start;
  pointer-events: none;
}

.scene-overlay .status {
  align-self: end;
  background: #08121bca;
  border: 1px solid #38506a;
  padding: 10px 12px;
  border-radius: 12px;
  font-size: 13px;
  max-width: 310px;
}

.scene-overlay .status b {
  display: block;
  color: var(--blue);
  font-size: 10px;
  letter-spacing: .08em;
  margin-bottom: 3px;
}

.event-description {
  margin: 15px 0 20px;
  color: #d1deea;
  font-size: 19px;
  line-height: 1.65;
  max-width: 750px;
}

.choices {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 13px;
}

.choice {
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: stretch;
  border: 0;
  border-radius: 0;
  background: transparent;
  flex: 1;
  width: 100%;
  padding: 18px;
  min-width: 0;
}

.choice .art {
  border-radius: 12px;
  background: radial-gradient(ellipse,#365376,#172239);
  height: 145px;
}

.choice h3 {
  font: 700 15px/1.45 'Nunito Sans',sans-serif;
  font-family: 'Outfit',sans-serif;
  font-size: 18px;
  line-height: 1.4;
  min-height: 0;
  margin-bottom: 10px;
}

.choice p {
  line-height: 1.75;
  min-height: 0;
  font-size: 15px;
  color: #d0dced;
}

.choice .impact {
  margin-top: auto;
  border-top: 1px solid var(--line);
  padding-top: 10px;
  font-size: 12px;
  line-height: 1.65;
  color: #ffdfb1;
  display: none;
}

.choice .letter {
  font: 12px monospace;
  color: var(--orange);
}

.operating {
  border: 1px solid #39516a;
  border-radius: 8px;
  color: var(--muted);
  margin-bottom: 17px;
  font-size: 13px;
  padding: 12px 16px;
}

.inventory {
  display: grid;
  gap: 9px;
}

.inventory button {
  text-align: left;
  border-radius: 12px;
  padding: 12px;
  font-size: 13px;
}

.inventory button strong {
  display: block;
  color: var(--blue);
}

.inventory button small {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-top: 3px;
}

.inventory button .uses {
  float: right;
  color: var(--orange);
}

.science-meter {
  font-size: 28px;
  color: var(--green);
}

.journal-entry {
  font-size: 11px;
  padding: 10px 0;
  border-bottom: 1px solid #24374a;
}

.journal-entry b {
  display: block;
  color: #d4e0eb;
  font-weight: 500;
}

.journal-entry small {
  color: var(--muted);
}

.feedback {
  margin-top: 20px;
  border-left: 3px solid var(--blue);
  animation: appear .4s;
  padding: 26px;
  scroll-margin-top: 20px;
}

.feedback.good {
  border-left-color: var(--green);
}

.feedback.bad {
  border-left-color: var(--red);
}

.feedback p {
  color: #d0deeb;
  margin: 10px 0;
}

.feedback .deltas {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 14px 0;
}

.delta {
  font-size: 12px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 5px;
}

.delta.negative {
  color: var(--red);
}

.delta.positive {
  color: var(--green);
}

.source {
  font-size: 12px;
}

.fact {
  margin: 15px 0;
  border: 1px solid #2f4b64;
  border-radius: 15px;
  padding: 18px;
  background: #101f33;
}

.fact b {
  font-size: 10px;
  color: var(--blue);
  letter-spacing: .12em;
}

.fact p {
  font-size: 13px;
  margin: 6px 0;
}

.activity {
  padding: 24px;
}

.activity canvas {
  width: 100%;
  height: 340px;
  display: block;
  border: 1px solid #38516b;
  touch-action: none;
  background: #070e18;
  margin: 20px 0 12px;
  border-radius: 18px;
}

.activity .controls {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
}

.activity .controls p {
  font-size: 13px;
}

.activity .readout {
  font: 12px monospace;
  color: var(--green);
  margin: 10px 0;
  font-size: 14px;
}

.activity input[type=range] {
  width: 100%;
  accent-color: var(--orange);
  min-height: 35px;
  height: 44px;
}

.activity label {
  display: block;
  font-size: 13px;
  margin: 18px 0;
}

.collection {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 12px;
  margin: 16px 0;
}

.collection .panel {
  padding: 18px;
}

.collection p {
  font-size: 12px;
  margin: 8px 0;
}

.report {
  max-width: 1000px;
  margin: auto;
}

.report .result {
  padding: 35px;
}

.report .result h1 {
  font-size: 60px;
  margin: 16px 0;
}

.report-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 20px;
}

.report-grid .panel {
  padding: 24px;
}

.report ul {
  color: var(--muted);
  padding-left: 20px;
  font-size: 13px;
}

.death-banner {
  background: radial-gradient(ellipse,#491c2a,#0b111c);
  border: 1px solid #e0738d;
  border-radius: 12px;
  text-align: center;
  margin: 20px 0;
  animation: appear 1s;
  margin-top: 12px;
  padding: 24px;
}

.death-banner h2 {
  color: var(--red);
  font-size: 26px;
}

.flatline {
  height: 2px;
  background: var(--red);
  width: 200px;
  margin: 22px auto;
  box-shadow: 0 0 14px var(--red);
}

dialog {
  color: var(--ink);
  background: #111e2f;
  border: 1px solid #49647f;
  border-radius: 14px;
  padding: 30px;
  width: min(850px,calc(100% - 28px));
  max-height: 85vh;
}

dialog::backdrop {
  background: #020811cf;
  backdrop-filter: blur(7px);
}

dialog h2 {
  margin-bottom: 20px;
}

dialog p {
  margin: 10px 0;
}

dialog .source-row {
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}

dialog .source-row p {
  font-size: 13px;
}

dialog input {
  color: white;
  padding: 12px;
  background: #0a1523;
  border: 1px solid #4b6580;
  border-radius: 7px;
  width: 100%;
  margin: 8px 0;
}

dialog select {
  color: white;
  padding: 12px;
  background: #0a1523;
  border: 1px solid #4b6580;
  border-radius: 7px;
  width: 100%;
  margin: 8px 0;
}

.close {
  position: absolute;
  right: 12px;
  top: 10px;
  font-size: 22px;
  padding: 0 8px;
}

#notice {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: #18364b;
  border: 1px solid var(--blue);
  padding: 12px 20px;
  border-radius: 9px;
  z-index: 80;
  display: none;
  font-size: 13px;
  max-width: 90vw;
}

#cinema {
  position: fixed;
  inset: 0;
  z-index: 90;
  background: #030a14;
  display: flex;
