  background: #182e42;
}

.launcher-summary b {
  color: #b8e2ff;
}

.launcher-summary>span {
  font-size: 12px;
  color: #d0dfed;
}

.launcher-summary p {
  margin: 4px 0 0;
  font-size: 11px;
}

.difficulty-brief {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: 16px 0;
  padding: 13px 16px;
  border-radius: 11px;
  background: #1b3047;
  border: 1px solid #7997b33d;
  color: #c7d9ea;
  font-size: 12px;
  line-height: 1.8;
}

.difficulty-brief b {
  color: #cce7fc;
}

.difficulty-brief span:last-child {
  flex-basis: 100%;
}

.launch-report {
  padding: 20px 23px;
  margin-top: 24px;
  border: 1px solid #a8bbce;
  border-radius: 16px;
  background: #fff;
}

.report .launch-report {
